package com.example.appbe.finance.account;

import com.example.appbe.user.User;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;

@Entity
@Table(name = "financial_accounts")
public class FinancialAccount {
    @Id
    private Long id;

    // Shared primary key: the profile uses the id generated by accounts.
    @MapsId
    @OneToOne(fetch = FetchType.LAZY, optional = false, cascade = {CascadeType.PERSIST, CascadeType.MERGE})
    @JoinColumn(name = "id", nullable = false)
    private Account account;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private FinancialAccountType type;

    @Column(name = "opening_balance", nullable = false, precision = 19, scale = 4)
    private BigDecimal openingBalance = BigDecimal.ZERO;

    @Column(name = "balance_start_date", nullable = false)
    private LocalDate balanceStartDate;

    protected FinancialAccount() {}

    public FinancialAccount(User user, String name, FinancialAccountType type, String currency,
                            BigDecimal openingBalance, LocalDate balanceStartDate) {
        this.account = new Account(user, name, currency, AccountKind.ORDINARY);
        this.type = type;
        this.openingBalance = openingBalance;
        this.balanceStartDate = balanceStartDate;
    }

    public Long getId() { return id; }
    public Account getAccount() { return account; }
    public User getUser() { return account.getUser(); }
    public void setUser(User user) { account.setUser(user); }
    public String getName() { return account.getName(); }
    public void setName(String name) { account.setName(name); }
    public FinancialAccountType getType() { return type; }
    public void setType(FinancialAccountType type) { this.type = type; }
    public String getCurrency() { return account.getCurrency(); }
    public void setCurrency(String currency) { account.setCurrency(currency); }
    public BigDecimal getOpeningBalance() { return openingBalance; }
    public void setOpeningBalance(BigDecimal openingBalance) { this.openingBalance = openingBalance; }
    public LocalDate getBalanceStartDate() { return balanceStartDate; }
    public void setBalanceStartDate(LocalDate date) { balanceStartDate = date; }
    public boolean isActive() { return account.isActive(); }
    public void setActive(boolean active) { account.setActive(active); }
    public Instant getCreatedAt() { return account.getCreatedAt(); }
    public Instant getUpdatedAt() { return account.getUpdatedAt(); }
}
